package com.acme.payments.gateway;

import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;

/**
 * Submits cardholder charge data to the external payment gateway.
 */
public class PaymentGatewayClient {

    private static final String GATEWAY_ENDPOINT = "http://payments-gw.internal.example.com:8080/api/v1/charge";

    public String submitCharge(String cardNumber, String cardholderName,
                               String cvv, String expiry, double amount) throws Exception {
        String payload = String.format(
                "{\"card_number\":\"%s\",\"cardholder\":\"%s\",\"cvv\":\"%s\",\"expiry\":\"%s\",\"amount\":%.2f}",
                cardNumber, cardholderName, cvv, expiry, amount);

        URL url = new URL(GATEWAY_ENDPOINT);
        HttpURLConnection conn = (HttpURLConnection) url.openConnection();
        conn.setRequestMethod("POST");
        conn.setRequestProperty("Content-Type", "application/json");
        conn.setDoOutput(true);

        try (OutputStream os = conn.getOutputStream()) {
            os.write(payload.getBytes(StandardCharsets.UTF_8));
        }

        int status = conn.getResponseCode();
        if (status != 200) {
            throw new IllegalStateException("Gateway rejected charge: HTTP " + status);
        }
        return "charge-submitted";
    }
}
