package com.example.account.reset;

import java.io.OutputStream;
import java.net.HttpURLConnection;
import java.net.URL;
import java.nio.charset.StandardCharsets;
import java.util.UUID;

import org.springframework.web.bind.annotation.PostMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

/**
 * 密码重置：生成重置令牌并调用内部通知服务发送邮件。
 */
@RestController
public class PasswordResetController {

    private static final String NOTIFY_URL = "http://notify.internal.example.com:8080/mail/send";

    @PostMapping("/password/reset")
    public String requestReset(@RequestParam("email") String email) {
        String token = UUID.randomUUID().toString();
        return sendResetMail(email, token);
    }

    @PostMapping("/password/reset/admin")
    public String adminReset(@RequestParam("email") String email,
                             @RequestParam("token") String token) {
        return sendResetMail(email, token);
    }

    private String sendResetMail(String email, String token) {
        String link = "http://account.example.com/reset?token=" + token;
        String payload = "{\"to\":\"" + email + "\",\"body\":\"reset link: " + link + "\"}";
        try {
            HttpURLConnection conn = (HttpURLConnection) new URL(NOTIFY_URL).openConnection();
            conn.setRequestMethod("POST");
            conn.setDoOutput(true);
            try (OutputStream os = conn.getOutputStream()) {
                os.write(payload.getBytes(StandardCharsets.UTF_8));
            }
            return "sent";
        } catch (Exception e) {
            return "error";
        }
    }
}
