package payment

import (
	"bytes"
	"encoding/json"
	"io"
	"net/http"
)

// ChargeRequest mirrors the fields collected by the checkout frontend.
type ChargeRequest struct {
	OrderID    string `json:"order_id"`
	CardNumber string `json:"card_number"`
	CardHolder string `json:"card_holder"`
	Expiry     string `json:"expiry"`
	CVV        string `json:"cvv"`
	Amount     int    `json:"amount"`
}

// HandleCharge accepts raw cardholder data from the checkout frontend
// and forwards it to the legacy ChargeWay gateway v1 plain-HTTP API.
func HandleCharge(w http.ResponseWriter, r *http.Request) {
	var req ChargeRequest
	if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
		http.Error(w, "invalid payload", http.StatusBadRequest)
		return
	}
	body, err := json.Marshal(req)
	if err != nil {
		http.Error(w, "encode failed", http.StatusInternalServerError)
		return
	}
	resp, err := http.Post("http://api.chargeway-gw.com/v1/charges",
		"application/json", bytes.NewReader(body))
	if err != nil {
		http.Error(w, "gateway unreachable", http.StatusBadGateway)
		return
	}
	defer resp.Body.Close()
	out, _ := io.ReadAll(resp.Body)
	w.Write(out)
}
