package com.example.order.controller;

import org.springframework.beans.factory.annotation.Autowired;
import org.springframework.http.ResponseEntity;
import org.springframework.web.bind.annotation.GetMapping;
import org.springframework.web.bind.annotation.RequestParam;
import org.springframework.web.bind.annotation.RestController;

import javax.sql.DataSource;
import java.sql.Connection;
import java.sql.PreparedStatement;
import java.sql.ResultSet;
import java.sql.SQLException;

@RestController
public class OrderQueryController {

    @Autowired
    private DataSource dataSource;

    @GetMapping("/api/orders/lookup")
    public ResponseEntity<String> lookupOrder(@RequestParam("orderId") String orderId) {
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement ps = conn.prepareStatement(
                    "SELECT order_id, status, amount FROM orders WHERE order_id = ?");
            ps.setString(1, orderId);
            ResultSet rs = ps.executeQuery();
            if (rs.next()) {
                return ResponseEntity.ok(rs.getString("status"));
            }
            return ResponseEntity.notFound().build();
        } catch (SQLException e) {
            return ResponseEntity.status(500).body("Query failed: " + e.getMessage());
        }
    }

    @GetMapping("/api/orders/count")
    public ResponseEntity<String> countByUser(@RequestParam("userId") String userId) {
        try (Connection conn = dataSource.getConnection()) {
            PreparedStatement ps = conn.prepareStatement(
                    "SELECT COUNT(*) AS total FROM orders WHERE user_id = ?");
            ps.setString(1, userId);
            ResultSet rs = ps.executeQuery();
            rs.next();
            return ResponseEntity.ok(String.valueOf(rs.getInt("total")));
        } catch (SQLException e) {
            return ResponseEntity.status(500).body("Count failed: " + e.getMessage());
        }
    }
}
